import{_ as i,o,c as a,a0 as t}from"./chunks/framework.BxrwG5q5.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),n={name:"guide/troubleshooting.md"};function r(s,e,l,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><blockquote><p>See also: <a href="/config/guide/self-hosting.html">Self-Hosting Guide</a> · <a href="/config/api/cloud-functions.html">Cloud Functions</a></p></blockquote><p>Common issues and fixes when running your @jewel998/config deployment.</p><h2 id="grpc-5-not-found-in-function-logs" tabindex="-1">&quot;gRPC 5 NOT_FOUND&quot; in function logs <a class="header-anchor" href="#grpc-5-not-found-in-function-logs" aria-label="Permalink to &quot;&quot;gRPC 5 NOT_FOUND&quot; in function logs&quot;">​</a></h2><p>The composite index for <code>clientIds</code> isn&#39;t deployed. Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">firebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firestore:indexes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project-id</span></span></code></pre></div><h2 id="cors-errors-calling-the-api" tabindex="-1">CORS errors calling the API <a class="header-anchor" href="#cors-errors-calling-the-api" aria-label="Permalink to &quot;CORS errors calling the API&quot;">​</a></h2><p>If you see CORS errors when calling <code>https://your-project.web.app/api/v1/config</code>:</p><ol><li>Ensure hosting is deployed: <code>firebase deploy --only hosting</code></li><li>The hosting config includes CORS headers for <code>/api/**</code></li><li>As a fallback, call the function URL directly: <code>https://REGION-your-project.cloudfunctions.net/getConfig</code> (replace <code>REGION</code> with your configured region, e.g., <code>asia-south1</code>)</li></ol><h2 id="permission-denied-on-firestore" tabindex="-1">&quot;Permission denied&quot; on Firestore <a class="header-anchor" href="#permission-denied-on-firestore" aria-label="Permalink to &quot;&quot;Permission denied&quot; on Firestore&quot;">​</a></h2><p>Make sure you&#39;ve deployed the security rules: <code>firebase deploy --only firestore:rules</code></p><h2 id="cloud-functions-returning-500" tabindex="-1">Cloud Functions returning 500 <a class="header-anchor" href="#cloud-functions-returning-500" aria-label="Permalink to &quot;Cloud Functions returning 500&quot;">​</a></h2><p>Check the function logs: Firebase Console → Functions → Logs. Common causes:</p><ul><li>Missing Firestore index (see above)</li><li>Database name mismatch (if you have a non-standard database name, see <code>functions/src/utils/firestore.ts</code>)</li></ul><h2 id="portal-shows-blank-page" tabindex="-1">Portal shows blank page <a class="header-anchor" href="#portal-shows-blank-page" aria-label="Permalink to &quot;Portal shows blank page&quot;">​</a></h2><p>Ensure the environment variables in <code>.env.production</code> match your Firebase project. Rebuild and redeploy.</p><h2 id="sdk-returns-undefined-values" tabindex="-1">SDK returns undefined values <a class="header-anchor" href="#sdk-returns-undefined-values" aria-label="Permalink to &quot;SDK returns undefined values&quot;">​</a></h2><ol><li>Check that your API key is active (not revoked) in the portal</li><li>Verify <code>baseUrl</code> points to your deployment</li><li>Check browser console — if you see 401/403, the SDK&#39;s <a href="/config/api/">circuit breaker</a> will stop retrying for 5 minutes</li><li>If using <code>createConfig</code>, call <code>client.destroy()</code> and reinitialize to reset the circuit breaker. With <code>initConfig</code>, reload the page.</li></ol><h2 id="sdk-stops-making-requests-circuit-breaker" tabindex="-1">SDK stops making requests (circuit breaker) <a class="header-anchor" href="#sdk-stops-making-requests-circuit-breaker" aria-label="Permalink to &quot;SDK stops making requests (circuit breaker)&quot;">​</a></h2><p>If the SDK receives a 400, 401, or 403 error, it activates a circuit breaker that blocks all requests for 5 minutes. This prevents hammering a misconfigured endpoint. After the cooldown, it automatically retries once.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/guide/self-hosting.html">Self-Hosting Guide</a> — Full deployment steps</li><li><a href="/config/api/cloud-functions.html">Cloud Functions Reference</a> — Function configuration and deployment</li><li><a href="/config/guide/performance.html">Performance Tuning</a> — Region selection and latency optimization</li><li><a href="/config/api/">SDK Reference</a> — Circuit breaker and error handling details</li></ul>',22)])])}const g=i(n,[["render",r]]);export{p as __pageData,g as default};
